<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\GdprConsent\Infrastructure\Driver\Rest;

use DateTime;
use Throwable;
use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use OpenApi\Attributes as OA;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Features\Oidc\GdprConsent\Domain\GdprConsentRecord;
use Civi\Lughauth\Features\Oidc\GdprConsent\Domain\Gateway\GdprConsentGateway;

final class MeConsentsHistoryController
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly Context $context,
        private readonly GdprConsentGateway $gateway,
    ) {
    }

    #[OA\Get(
        path: '/api/me/consents/history',
        summary: 'List GDPR consent changes history, newest first',
        tags: ['Me - GDPR Consents'],
        security: [['bearerAuth' => []]],
        responses: [
            new OA\Response(
                response: 200,
                description: 'OK',
                content: new OA\JsonContent(type: 'array', items: new OA\Items(ref: '#/components/schemas/MeConsentHistoryApiDTO'))
            ),
            new OA\Response(response: 401, description: 'Unauthorized'),
        ]
    )]
    public function history(ServerRequestInterface $request, ResponseInterface $response): ResponseInterface
    {
        $this->logDebug('Get me/consents/history');
        $span = $this->startSpan('Get me/consents/history');
        try {
            $identity = $this->context->getIdentity();
            if ($identity->anonymous || null === $identity->id) {
                throw new UnauthorizedException();
            }

            $records = $this->gateway->historyConsents($identity->id);
            $dtos = array_map([$this, 'mapRecord'], $records);

            $encoded = json_encode($dtos);
            $response->getBody()->write($encoded !== false ? $encoded : '[]');
            return $response->withStatus(200)->withHeader('Content-Type', 'application/json');
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    private function mapRecord(GdprConsentRecord $record): MeConsentHistoryApiDTO
    {
        $dto = new MeConsentHistoryApiDTO();
        $dto->uid = $record->uid;
        $dto->purposeUid = $record->purposeUid;
        $dto->granted = $record->granted;
        $dto->decisionAt = $record->decisionAt?->format(DateTime::ATOM);
        $dto->ipAddress = $record->ipAddress;
        $dto->userAgent = $record->userAgent;
        return $dto;
    }
}
